        await queryRunner.query(`DROP INDEX "User_username_key"`);
        await queryRunner.query(`ALTER TABLE "User" RENAME TO "temporary_User"`);
        await queryRunner.query(`CREATE TABLE "User" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "email" text, "username" text NOT NULL, "passwordHash" text NOT NULL, "locale" text NOT NULL DEFAULT ('zh-CN'), "defaultFamilyId" integer, "createdAt" datetime NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updatedAt" datetime NOT NULL, CONSTRAINT "User_defaultFamilyId_fkey" FOREIGN KEY ("defaultFamilyId") REFERENCES "Family" ("id") ON DELETE SET NULL ON UPDATE CASCADE)`);
        await queryRunner.query(`INSERT INTO "User"("id", "email", "username", "passwordHash", "locale", "defaultFamilyId", "createdAt", "updatedAt") SELECT "id", "email", "username", "passwordHash", "locale", "defaultFamilyId", "createdAt", "updatedAt" FROM "temporary_User"`);
        await queryRunner.query(`DROP TABLE "temporary_User"`);
        await queryRunner.query(`CREATE UNIQUE INDEX "User_email_key" ON "User" ("email") `);
