        await queryRunner.query(`INSERT INTO "FamilyInvite"("id", "familyId", "token", "createdById", "expiresAt", "revokedAt", "createdAt") SELECT "id", "familyId", "token", "createdById", "expiresAt", "revokedAt", "createdAt" FROM "temporary_FamilyInvite"`);
